// BestTV вэб чат — { sessionId, message, name } задална → AI Agent-д өгнө.
//
// ⚠️⚠️ FB/IG-ТЭЙ ЯГ ИЖИЛ ХАРИУЛТ ӨГӨХ ЁСТОЙ. Өмнө нь энэ node нь
// зөвхөн текст задалдаг байсан тул вэбээр үнэ/данс/холбоо асуухад
// AI нь МЭДЭЭЛЛИЙГ ЗОХИОДОГ байв (FB дээр deterministic хариу байсан
// атал вэб дээр байгаагүй) — нэг платформ хоёр өөр хариу өгнө.
const body = $input.first().json.body || {};
const sessionId = String(body.sessionId || "web_anon").slice(0, 64);
const userText = String(body.message || "").trim();
const name = (body.name || "").trim();
const NL = String.fromCharCode(10);

if (!userText) {
  return [{ json: { psid: sessionId, userText: "", agentInput: "", empty: true, directReply: "" } }];
}

const nameLine = name ? ("Хэрэглэгчийн нэр: " + name) : "";

// ⚠️ Холбоо барих/багцын асуултад AI зохиодог тул deterministic хариу
// бэлдэнэ (Build Messages түүнийг AI-аас ДЭЭГҮҮР ашиглана).
const lower = (userText || '').toLowerCase();
const contactTriggers = ['утас','дугаар','хаяг','холбоо','холбогд','имэйл','мэйл',
  'байршил','ажлын цаг','социал','фэйсбүүк','facebook','instagram','инстаграм',
  'бидний тухай','танай тухай','хэн бэ','хаягтай','утастай','phone','contact'];
const _hasEmailAddr = /[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i.test(userText || '');
const needsContact = !_hasEmailAddr && contactTriggers.some((t) => lower.includes(t));

let directReply = '';
if (needsContact) {
  try {
    const s = await this.helpers.httpRequest({
      method: 'GET', url: 'http://besttv-backend:4100/api/settings/socials', json: true, timeout: 4000,
      /* ⚠️ throttle-ыг тойрно — 30 хүсэлтээс 10 нь 429 болдог байв,
         тэгэхэд directReply хоосон үлдэж AI холбоо барихыг ЗОХИОНО */
      headers: { 'x-bot-secret': '__BOT_SECRET__' },
    });
    const parts = ['📺 BestTV — Монголын кино, цувралын онлайн сан', ''];
    if (s && s.phone) parts.push('📞 Утас: ' + s.phone);
    /**
     * ⚠️⚠️ ИМЭЙЛ ЗААВАЛ ГАРНА — админ socials-д тохируулаагүй ч.
     *
     * БОДИТ АЛДАА: Settings.socials бүх талбар ХООСОН байсан тул
     * «холбоо барих» асуултад чатбот зөвхөн вэб хаяг өгч, хэрэглэгч
     * хаана хандахаа мэдэхгүй үлддэг байв. Тохиргоо хоосон байх нь
     * хэрэглэгчид хариу өгөхгүй байх ШАЛТГААН БИШ.
     */
    parts.push('✉️ Имэйл: ' + ((s && s.email) || 'support@besttv.us'));
    if (s && s.facebook) parts.push('💬 Facebook: ' + s.facebook);
    if (s && s.instagram) parts.push('📷 Instagram: ' + s.instagram);
    parts.push('', '🌐 Вэб: https://besttv.us');
    parts.push('', 'Эсвэл энд шууд бичээрэй — админ хариулна 😊');
    directReply = parts.join(NL);
  } catch (e) {
    /* ⚠️ API унасан ч ХООСОН БУЦААХГҮЙ — өмнө нь directReply=''
       болоод AI холбоо барих мэдээллийг ЗОХИОДОГ байв (худал утас/
       имэйл өгөх эрсдэл). Хамгийн багадаа имэйл + вэб хаягийг өгнө. */
    directReply = ['📺 BestTV — Монголын кино, цувралын онлайн сан', '',
      '✉️ Имэйл: support@besttv.us', '', '🌐 Вэб: https://besttv.us', '',
      'Эсвэл энд шууд бичээрэй — админ хариулна 😊'].join(NL);
  }
}

// ⚠️ БАГЦЫН ҮНЭ — AI үнэ зохиовол хэрэглэгч төөрөлдөнө. Бодит үнийг татна.
const priceTriggers = ['багц','үнэ','төлбөр','хэд вэ','ханш','тариф','захиалга','subscribe','price'];
const needsPricing = priceTriggers.some((t) => lower.includes(t));
let plansText = '';
if (needsPricing) {
  try {
    const plans = await this.helpers.httpRequest({
      method: 'GET', url: 'http://besttv-backend:4100/api/plans', json: true, timeout: 4000,
      /* ⚠️ throttle → 429 → AI ҮНЭ ЗОХИОНО. Яг сэргийлэх гэсэн зүйл. */
      headers: { 'x-bot-secret': '__BOT_SECRET__' },
    });
    if (Array.isArray(plans) && plans.length) {
      const fmt = function(n){ var s=String(Math.round(Number(n)||0)),o='',c=0;
        for(var i=s.length-1;i>=0;i--){o=s[i]+o;c++;if(c%3===0&&i>0)o=','+o;} return o+'₮'; };
      const lines = ['📦 BestTV-ийн багцууд:', ''];
      plans.forEach(function(p){
        lines.push('• ' + p.name + ' — ' + fmt(p.price) + ' / ' + p.durationDays + ' хоног');
        if (p.description) lines.push('  ' + p.description);
      });
      lines.push('', '👉 Багц авах: https://besttv.us/pricing');
      plansText = lines.join(NL);
    }
  } catch (e) { plansText = ''; }
}
if (plansText) directReply = plansText;

/**
 * ⚠️⚠️ ДАНСНЫ МЭДЭЭЛЭЛ — AI-д ХЭЗЭЭ Ч ЗОХИОЛГОХГҮЙ.
 *
 * Буруу дансны дугаар өгвөл хэрэглэгчийн МӨНГӨ ӨӨР ХҮН РҮҮ очно —
 * буцаах боломжгүй, платформын нэр хүнд унана. Тиймээс бодит дансыг
 * DB-ээс татаж deterministic хариу бэлдэнэ.
 *
 * ⚠️ ГҮЙЛГЭЭНИЙ УТГА нь хэрэглэгч/захиалга бүрт ӨӨР (жишээ BTV-XXXX)
 *    тул ЭНД бичихгүй — сайтаас авахыг зааварчилна.
 */
const bankTriggers = ['данс','дансаар','шилжүүл','хаан банк','хаанбанк','голомт',
  'хас банк','төрийн банк','account','гүйлгээ','дансны дугаар'];
const needsBank = bankTriggers.some((t) => lower.includes(t));
if (needsBank) {
  try {
    /* ⚠️ Зам нь /bank/accounts — /settings/bank БАЙХГҮЙ (404).
       Олон данс байж болно тул идэвхтэйг нь бүгдийг харуулна. */
    const b = await this.helpers.httpRequest({
      method: 'GET', url: 'http://besttv-backend:4100/api/bank/accounts', json: true, timeout: 4000,
      headers: { 'x-bot-secret': '__BOT_SECRET__' },
    });
    const accs = (b && Array.isArray(b.accounts))
      ? b.accounts.filter(function (a) { return a && a.isActive && a.accountNumber; })
      : [];
    if (b && b.enabled && accs.length) {
      const bl = ['🏦 Дансаар шилжүүлэх:', ''];
      accs.forEach(function (a) {
        bl.push((a.bankName ? a.bankName + ': ' : '') + a.accountNumber
          + (a.accountName ? '  (' + a.accountName + ')' : ''));
      });
      bl.push('', '⚠️ ГҮЙЛГЭЭНИЙ УТГЫГ заавал бичнэ — сайт дээр багцаа',
        'сонгоод «Дансаар шилжүүлэх» гэхэд ТАНД зориулсан утга гарна.',
        '', 'Шилжүүлээд баримтын зургаа энд илгээгээрэй 📷');
      if (b.note) bl.push('', b.note);
      bl.push('', '👉 https://besttv.us/pricing');
      directReply = bl.join(NL);
    }
  } catch (e) {
    /* ⚠️ API унасан ч AI-д данс зохиолгохгүй — заавар руу чиглүүлнэ */
    directReply = ['🏦 Дансаар шилжүүлэх:', '',
      'Сайт дээр багцаа сонгоод «Дансаар шилжүүлэх» гэхэд дансны',
      'дугаар болон ТАНД зориулсан гүйлгээний утга гарч ирнэ.',
      '', 'Шилжүүлээд баримтын зургаа энд илгээгээрэй 📷',
      '', '👉 https://besttv.us/pricing'].join(NL);
  }
}


const agentInput = [nameLine, "=== ХЭРЭГЛЭГЧИЙН МЕССЕЖ ===", userText].filter(Boolean).join(NL);

return [{ json: { psid: sessionId, userText, agentInput, directReply } }];

// AI хариунаас [SEARCH:keyword] салгана.
const prep = $('Prep').first().json;
const psid = prep.psid;
const platform = prep.platform || 'facebook';
let raw = ($input.first().json.output || '').trim();
let keyword = '';
const m = raw.match(/\[SEARCH:\s*([^\]]*)\]/i);
if (m) keyword = (m[1] || '').trim();
let replyText = raw.replace(/\[SEARCH:[^\]]*\]/ig, '').trim();

// Markdown цэвэрлэх: [текст](url) → "текст url", ** __ устгах
function stripMd(s){ s=String(s||''); var r='',i=0;
  while(i<s.length){ if(s[i]==='['){ var c=s.indexOf('](',i);
    if(c!==-1){ var e=s.indexOf(')',c+2); if(e!==-1){ var t=s.slice(i+1,c).trim();
      var u=s.slice(c+2,e).trim(); r+=(t===u||!t)?u:(t+' '+u); i=e+1; continue; } } }
    r+=s[i]; i++; }
  r=r.split('**').join('').split('__').join('');
  var parts=r.split(' '); var out=[];
  for(var k=0;k<parts.length;k++){ if(k>0 && parts[k]!=='' && parts[k]===parts[k-1]) continue; out.push(parts[k]); }
  return out.join(' ').trim(); }
replyText = stripMd(replyText);

// ⚠️ FAQ ХАМГААЛАЛТ: AI ерөнхий үйл үгийг [SEARCH:]-д тавьсан бол хайхгүй
const kwLc = keyword.toLowerCase().replace(/\s+/g, ' ').trim();
const FAQ_STOP = ['үзэх','яаж үзэх','хэрхэн үзэх','багц','багцын үнэ','үнэ','төлбөр',
  'төлбөр төлөх','qpay','данс','дансаар','купон','хямдрал','урамшуулал','бүртгэл',
  'бүртгүүлэх','нэвтрэх','нууц үг','имэйл','төхөөрөмж','хэдэн төхөөрөмж','татах',
  'татаж авах','офлайн','чанар','интернэт','тусламж','холбоо барих','админ'];
if (FAQ_STOP.indexOf(kwLc) !== -1) keyword = '';

// ⚠️⚠️ ТӨРӨЛ ТАНИХ — «цуврал» гэдэг нь ОЛОН АНГИТ кино (SERIES).
//
// Өмнө нь «цуврал», «кино» хоёрыг FAQ_STOP-д хийж хайлтыг бүрмөсөн
// зогсоодог байв → чатбот өмнөх ярианы үлдэгдэл харуулж, хэрэглэгч
// «цуврал» гэж асуухад ЖИРИЙН КИНО санал болгодог байв (бодит гомдол).
//
// Одоо: төрлийг ТАНЬЖ type параметрээр backend-д дамжуулна.
// Хайх үг үлдээгүй ч type байвал backend тухайн төрлийн шинэ
// кинонуудыг буцаана.
var SERIES_WORDS = ['цуврал','олон ангит','олон ангийн','сериал','series','драм цуврал'];
var MOVIE_WORDS  = ['кино','уран сайхны','бүрэн хэмжээний','movie','film'];
var titleType = '';
for (var si = 0; si < SERIES_WORDS.length; si++) {
  if (kwLc.indexOf(SERIES_WORDS[si]) !== -1) { titleType = 'SERIES'; break; }
}
if (!titleType) {
  for (var mi = 0; mi < MOVIE_WORDS.length; mi++) {
    if (kwLc === MOVIE_WORDS[mi]) { titleType = 'MOVIE'; break; }
  }
}
/* Төрлийн үгийг түлхүүрээс хасна — «солонгос цуврал» → «солонгос» */
if (titleType) {
  var strip = titleType === 'SERIES' ? SERIES_WORDS : MOVIE_WORDS;
  var cleaned = kwLc;
  for (var ci = 0; ci < strip.length; ci++) cleaned = cleaned.split(strip[ci]).join(' ');
  keyword = cleaned.replace(/\s+/g, ' ').trim();
}

/**
 * ⚠️⚠️ AI [SEARCH:] МАРТСАН ҮЕИЙН НӨӨЦ — ХАМГИЙН ЧУХАЛ.
 *
 * БОДИТ АЛДАА: prompt-д дүрэм, жишээ (яг «agent kim») хүртэл байсан
 * атал AI нь [SEARCH:] тавихгүй, зөвхөн текстээр хариулдаг тохиолдол
 * гардаг. Тэгэхэд:
 *   • карт ОГТ гарахгүй (хэрэглэгч кино руу орох линкгүй)
 *   • бүр AI нь санах ойноосоо БАЙХГҮЙ кино нэрлэдэг
 *     («Crash Landing on You» — манай санд байхгүй, бодитоор гарсан)
 *
 * Тиймээс AI-д НАЙДАХГҮЙ: түлхүүр үг олдоогүй бол хэрэглэгчийн
 * мессежээс ӨӨРӨӨ гаргана. Хайлт хийвэл бодит кино л буцна —
 * зохиомол нэр карт болж гарах боломжгүй.
 */
if (!keyword && !titleType) {
  var uq = String(prep.userText || '').toLowerCase().replace(/\s+/g, ' ').trim();
  /**
   * FAQ/мэндчилгээ бол хайхгүй — deterministic хариу аль хэдийн бий.
   * ⚠️ indexOf (яг тэнцэл БИШ) — «багц хэд вэ», «сайн байна уу» гэх
   *    мэт нэмэлт үгтэй хувилбарыг ч барина. Өмнөх яг тэнцлийн
   *    шалгалт эдгээрийг АЛДАЖ, FAQ асуултаар кино хайдаг байв.
   */
  var SKIP = ['сайн байна','сайн уу','байна уу?','баярлалаа','баяртай','okay',
    'мэдээлэл','тусламж','туслаач','ойлголоо','за ойлголоо','тэгье'];
  var isSkip = false;
  for (var qi = 0; qi < SKIP.length; qi++) {
    if (uq.indexOf(SKIP[qi]) !== -1) { isSkip = true; break; }
  }
  /* FAQ_STOP-ын аль нэг үг мессежид БАЙВАЛ хайхгүй (deterministic хариу бий) */
  if (!isSkip) {
    for (var fi = 0; fi < FAQ_STOP.length; fi++) {
      if (FAQ_STOP[fi].length >= 3 && uq.indexOf(FAQ_STOP[fi]) !== -1) { isSkip = true; break; }
    }
  }
  /* Маш богино хариулт (за, тийм, ok) — хайх утгагүй */
  if (uq.length <= 4) isSkip = true;
  if (!isSkip && uq.length >= 3 && uq.length <= 60) {
    /* Төрлийн үг байвал таньж, түүнийг хасна */
    for (var s2 = 0; s2 < SERIES_WORDS.length; s2++) {
      if (uq.indexOf(SERIES_WORDS[s2]) !== -1) { titleType = 'SERIES'; break; }
    }
    var uq2 = uq;
    if (titleType) {
      for (var c2 = 0; c2 < SERIES_WORDS.length; c2++) uq2 = uq2.split(SERIES_WORDS[c2]).join(' ');
    }
    /* Асуултын дагавар үгсийг хасна — «байна уу», «үзмээр байна» г.м. */
    var TAIL = ['байна уу','бий юу','байгаа юу','үзмээр байна','үзье','санал болгооч',
      'олоод өгөөч','хайж өгөөч','байна','уу','вэ','бэ'];
    for (var t2 = 0; t2 < TAIL.length; t2++) uq2 = uq2.split(TAIL[t2]).join(' ');
    uq2 = uq2.replace(/[?!.,]/g, ' ').replace(/\s+/g, ' ').trim();
    if (uq2.length >= 2) keyword = uq2;
  }
}

/* ⚠️ Төрөл мэдэгдэж байвал түлхүүр үг хоосон ч ХАЙНА */
const doSearch = keyword.length >= 2 || titleType !== '';

// ⚠️⚠️ AI УНАСАН ТОХИОЛДОЛ (OpenAI 3 удаа алдсан).
//
// AI Agent-д onError: continueRegularOutput тавьсан тул урсгал
// үргэлжилнэ, гэхдээ output хоосон ирнэ. Ийм үед «Уучлаарай,
// дахин бичнэ үү» гэвэл хэрэглэгч буруугаа гэж бодно — үнэнийг
// хэлж, дахин оролдохыг урина.
if (!replyText) {
  replyText = doSearch
    ? 'Хайж байна...'
    : 'Уучлаарай, түр саатал гарлаа 🙏 Хэдхэн секундын дараа дахин бичээрэй.';
}
return [{ json: { psid, keyword, titleType, doSearch, replyText, platform } }];

// Widget-д зориулсан эцсийн JSON: { reply, titles[] } + backend-д бичих _ingest.
const ex = $('Extract Keyword').first().json;
// ⚠️⚠️ deterministic хариу (холбоо/үнэ/данс) нь AI-аас ДЭЭГҮҮР.
//
// БОДИТ АЛДАА: вэб чат нь Prep-ийн directReply-ыг ОГТ уншдаггүй
// байсан тул FB дээр бодит үнэ/данс гардаг атал ВЭБ дээр AI нь
// мэдээллийг ЗОХИОДОГ байв — нэг платформ хоёр өөр хариу.
let _direct = "";
try { _direct = ($('Prep').first().json.directReply || "").trim(); } catch (e) {}
const replyText = _direct || (ex.replyText || '').trim() || 'Уучлаарай, дахин бичнэ үү.';

let raw = [];
try {
  /**
   * ⚠️⚠️ .all() — .first() БИШ. ЭНЭ БОЛ ГОЛ АЛДАА БАЙВ.
   *
   * /titles/search нь ЦЭВЭР МАССИВ буцаадаг. n8n HTTP node нь
   * массив хариуг ОЛОН ITEM болгон ЗАДАЛДАГ тул .first().json нь
   * массив БИШ, ЭХНИЙ КИНО (объект) болно. Тэгэхэд Array.isArray
   * нь false → raw хоосон үлдэж КАРТ ОГТ ГАРДАГГҮЙ байв
   * (FB дээр аль хэдийн засагдсан, вэб дээр үлдсэн байсан).
   */
  const items = $('Search Titles').all();
  raw = items.map(function (it) { return it.json; })
    .filter(function (x) { return x && (x.slug || x.id); });
  /* Backend {data:[...]} хэлбэрээр буцаах тохиолдол */
  if (raw.length === 1 && Array.isArray(raw[0] && raw[0].data)) raw = raw[0].data;
} catch (e) { raw = []; }

const triedSearch = ex.doSearch === true;
const list = triedSearch ? raw : [];

// Эхний 6 киног widget-ийн карт болгоно
const titles = list.slice(0, 6).map(function (t) {
  return {
    id: t.id || null,
    title: t.title || '',
    slug: t.slug || '',
    posterUrl: t.posterUrl || null,
    url: t.slug ? ('https://besttv.us/movie/' + t.slug) : null,
    year: (t.year != null) ? Number(t.year) : null,
    rating: (t.rating != null) ? Number(t.rating) : null,
  };
});

return [{ json: {
  reply: replyText,
  titles: titles,
  _ingest: {
    sessionId: String(($('Prep').first().json.psid) || '').slice(0, 64),
    userText: String(($('Prep').first().json.userText) || '').trim(),
    assistantText: String(replyText || '').trim(),
    titles: titles,
  },
} }];
